Visuals:
```js
function normalizeVisuals(list, isProjectile=false){
  if(!Array.isArray(list)) return [];
  return list.slice(0, isProjectile?8:12).map(v=>{
    if(!v||typeof v!=='object') return null;
    const shape=VALID_SHAPES.has(v.shape)?v.shape:'box';
    return {
      shape,
      position: arr3(v.position,[0,0,0],-4,4),
      rotation: arr3(v.rotation,[0,0,0],-720,720),
      scale: arr3(v.scale ?? v.size, [0.4,0.4,0.4], 0.02, 8),
      color: safeColor(v.color, '#8ec5ff'),
      emissive: v.emissive ? safeColor(v.emissive,'#000000') : null,
      metalness: num(v.metalness,0.15,0,1),
      roughness: num(v.roughness,0.55,0,1),
      opacity: num(v.opacity,1,0.12,1),
      tag: typeof v.tag==='string'?v.tag.slice(0,16):null,
    };
  }).filter(Boolean);
}
```
