function normalizeSpec(raw, prompt){
  const type = VALID_TYPES.has(raw.type)?raw.type:'physics_object';
  let visuals = normalizeVisuals(raw.visuals || raw.shapes || []);
  if(type!=='world_event' && visuals.length===0){ visuals=[{...default box...}]; }
  const projectileVisuals = normalizeVisuals(raw.projectile_visuals || raw.projectileVisuals || [], true);
  const p = raw.physics||{};
  const physics = {
    mass: num(p.mass, type==='vehicle'?300:4, 0.05, 800),
    restitution: num(p.restitution, 0.3, 0, 1.6),
    friction: num(p.friction, 0.5, 0, 2),
    collider: p.collider==='sphere'?'sphere':'box',
    gravityScale: num(p.gravityScale, 1, 0, 2.5),
    linearDamping: num(p.linearDamping, 0.12, 0, 1),
    angularDamping: num(p.angularDamping, 0.2, 0, 1),
    bouncy: !!p.bouncy || num(p.restitution,0,0,1.6) > 0.9,
  };
  const a = raw.action_behavior || raw.actionBehavior || {};
  const action = {
    mode: ['projectile','explode','deploy','drive','none'].includes(a.mode) ? a.mode : (type==='weapon'?'projectile':type==='vehicle'?'drive':type==='physics_object'?'deploy':'none'),
    projectile: typeof a.projectile==='string'?a.projectile.slice(0,28):'Orb',
    speed: num(a.speed, type==='weapon'?36:12, 0, 90),
    gravityScale: num(a.gravityScale, 1, 0, 2.5),
    onImpact: ['explode','bounce','stick','none'].includes(a.onImpact)?a.onImpact:'explode',
    explosionRadius: num(a.explosionRadius, 4, 1, 10),
    explosionForce: num(a.explosionForce, 12, 1, 40),
    cooldown: num(a.cooldown, type==='weapon'?0.4:1.2, 0.1, 3),
    spawnCount: Math.round(num(a.spawnCount,1,1,5)),
    spread: num(a.spread, 0.02, 0, 0.5),
    maxSpeed: num(a.maxSpeed, 16, 4, 32),
    acceleration: num(a.acceleration, 22, 5, 50),
    turnSpeed: num(a.turnSpeed, 2.2, 0.6, 4),
    projectileMass: num(a.projectileMass, 0.5, 0.05, 20),
    projectileScale: num(a.projectileScale, 1, 0.2, 3),
  };
  const w = raw.world_effect || raw.worldEffect || {};
  const worldEffect = {
    gravity: num(w.gravity, 1, 0, 2.5),
    skyColor: w.skyColor ? safeColor(w.skyColor,'#8ec9ff') : null,
    weather: ['rain','meteor','none'].includes(w.weather)?w.weather:'none',
    weatherRate: num(w.weatherRate, 2, 0.2, 8),
    duration: num(w.duration, 20, 5, 60),
  };
  let structure = null;
  if (raw.structure === 'tower' || (type==='physics_object' && /tower|skyscraper|stack/i.test(prompt))) { structure='tower'; }
  return { type, name: String(raw.name || titleFromPrompt(prompt)).slice(0,30), description: String(raw.description||'').slice(0,100), visuals, projectile_visuals: projectileVisuals, physics, action_behavior: action, world_effect: worldEffect, structure, source: raw.__source||'ai' };
}
