function makeGridTexture() {
  const size = 512;
  const c = document.createElement("canvas");
  c.width = c.height = size;
  const g = c.getContext("2d");
  g.fillStyle = "#e9efe3";
  g.fillRect(0, 0, size, size);

  // Soft organic speckle keeps the huge plane from looking flat
  for (let i = 0; i < 1500; i++) {
    const a = Math.random() * 0.045;
    g.fillStyle = `rgba(105,135,118,${a})`;
    g.fillRect(Math.random() * size, Math.random() * size, 1 + Math.random() * 2, 1 + Math.random() * 2);
  }

  // 10 x 10 cells, 1 metre per cell
  const step = size / 10;
  g.strokeStyle = "rgba(96,124,112,.16)";
  g.lineWidth = 1;
  for (let i = 0; i <= 10; i++) {
    const p = Math.round(i * step) + 0.5;
    g.beginPath(); g.moveTo(p, 0); g.lineTo(p, size); g.stroke();
    g.beginPath(); g.moveTo(0, p); g.lineTo(size, p); g.stroke();
  }
  g.strokeStyle = "rgba(82,112,100,.3)";
  g.lineWidth = 2;
  g.strokeRect(1, 1, size - 2, size - 2);

  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(220, 220);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
  return tex;
}

