function buildPlayer() {
  playerGroup = new THREE.Group();
  playerVisual = new THREE.Group();
  playerGroup.add(playerVisual);
  scene.add(playerGroup);

  const jacket = solid("#ff7a45", { roughness: 0.6 });
  const jacketDark = solid("#e05a32", { roughness: 0.65 });
  const pants = solid("#25344f", { roughness: 0.7 });
  const skin = solid("#ffd7b0", { roughness: 0.75 });
  const cream = solid("#f7f1df", { roughness: 0.55 });
  const visor = solid("#17324a", { roughness: 0.15, metalness: 0.55, emissive: "#4cc9f0", emissiveIntensity: 0.35 });
  const gold = solid("#ffd166", { roughness: 0.5, metalness: 0.2 });
  const boot = solid("#1b2537", { roughness: 0.8 });
  const mint = solid("#6ee7c8", { roughness: 0.4, emissive: "#2dd4bf", emissiveIntensity: 0.4 });

  const addMesh = (geo, mat, pos, parent = playerVisual) => {
    const m = new THREE.Mesh(geo, mat);
    m.position.set(pos[0], pos[1], pos[2]);
    m.castShadow = true;
    m.receiveShadow = true;
    parent.add(m);
    return m;
  };

  // Torso + belt
  addMesh(new THREE.CapsuleGeometry(0.3, 0.48, 5, 12), jacket, [0, 1.13, 0]);
  addMesh(new THREE.CylinderGeometry(0.305, 0.305, 0.09, 16), pants, [0, 0.86, 0]);
  addMesh(new THREE.BoxGeometry(0.16, 0.1, 0.06), gold, [0, 0.86, -0.3]);

  // Head + helmet + visor
  addMesh(new THREE.SphereGeometry(0.265, 20, 16), skin, [0, 1.66, 0]);
  const helmet = addMesh(new THREE.SphereGeometry(0.3, 20, 16), cream, [0, 1.71, 0.02]);
  helmet.scale.set(1.02, 0.86, 1.05);
  addMesh(new THREE.BoxGeometry(0.36, 0.145, 0.12), visor, [0, 1.66, -0.235]);
  addMesh(new THREE.BoxGeometry(0.38, 0.04, 0.14), gold, [0, 1.79, -0.2]);

  // Backpack + antenna
  addMesh(new THREE.BoxGeometry(0.42, 0.5, 0.24), gold, [0, 1.18, 0.3]);
  addMesh(new THREE.BoxGeometry(0.26, 0.16, 0.06), mint, [0, 1.28, 0.43]);
  addMesh(new THREE.CylinderGeometry(0.018, 0.018, 0.34, 6), boot, [0.14, 1.5, 0.32]);
  addMesh(new THREE.SphereGeometry(0.045, 8, 6), mint, [0.14, 1.68, 0.32]);

  // Arms (pivots so they can swing / aim)
  const makeArm = (side) => {
    const pivot = new THREE.Group();
    pivot.position.set(side * 0.35, 1.4, 0);
    playerVisual.add(pivot);
    const arm = new THREE.Mesh(new THREE.CapsuleGeometry(0.075, 0.36, 4, 8), jacket);
    arm.position.y = -0.26; arm.castShadow = true;
    pivot.add(arm);
    const cuff = new THREE.Mesh(new THREE.CylinderGeometry(0.085, 0.085, 0.1, 10), jacketDark);
    cuff.position.y = -0.47; cuff.castShadow = true;
    pivot.add(cuff);
    const hand = new THREE.Mesh(new THREE.SphereGeometry(0.095, 10, 8), skin);
    hand.position.y = -0.55; hand.castShadow = true;
    pivot.add(hand);
    return pivot;
  };
  playerVisual.userData.armL = makeArm(-1);
  playerVisual.userData.armR = makeArm(1);

  // Legs
  const makeLeg = (side) => {
    const pivot = new THREE.Group();
    pivot.position.set(side * 0.16, 0.82, 0);
    playerVisual.add(pivot);
    const leg = new THREE.Mesh(new THREE.CapsuleGeometry(0.095, 0.42, 4, 8), pants);
    leg.position.y = -0.33; leg.castShadow = true;
    pivot.add(leg);
    const shoe = new THREE.Mesh(new THREE.BoxGeometry(0.19, 0.14, 0.32), boot);
    shoe.position.set(0, -0.66, -0.05); shoe.castShadow = true;
    pivot.add(shoe);
    return pivot;
  };
  playerVisual.userData.legL = makeLeg(-1);
  playerVisual.userData.legR = makeLeg(1);

  // Weapon socket
  weaponMount = new THREE.Group();
  weaponMount.position.set(0.46, 1.3, -0.24);
  weaponMount.userData.base = weaponMount.position.clone();
  playerVisual.add(weaponMount);

  // Contact shadow (extra grounding, especially on low-end devices without shadows)
  blobShadow = new THREE.Mesh(
    new THREE.CircleGeometry(0.62, 28),
    new THREE.MeshBasicMaterial({ color: 0x1a2b20, transparent: true, opacity: 0.17, depthWrite: false })
  );
  blobShadow.rotation.x = -Math.PI / 2;
  blobShadow.position.y = 0.055;
  scene.add(blobShadow);

  playerGroup.position.set(0, 0.65, 0);
}

// ─────────────────────────────────────────────────────────────────────────────
//  CAMERA
// ─────────────────────────────────────────────────────────────────────────────
function cameraDesiredPosition(target) {
  const cp = Math.cos(cam.pitch);
  const offset = new THREE.Vector3(
    Math.sin(cam.yaw) * cp * cam.dist,
    Math.sin(cam.pitch) * cam.dist + 0.5,
    Math.cos(cam.yaw) * cp * cam.dist
  );
  const pos = target.clone().add(offset);
  pos.y = Math.max(0.62, pos.y);
  return pos;
}
function snapCamera() {
  const target = new THREE.Vector3(
    playerBody.position.x,
    playerBody.position.y + 0.9,
    playerBody.position.z
  );
  cam.target.copy(target);
  camera.position.copy(cameraDesiredPosition(target));
  camera.lookAt(cam.target);
}
function updateCamera(dt) {
  const driving = state.drivingEntity;
  const target = new THREE.Vector3();
  if (driving && !driving.dead) {
    target.set(driving.body.position.x, driving.body.position.y + 1.25, driving.body.position.z);
  } else {
    target.set(playerBody.position.x, playerBody.position.y + 0.9, playerBody.position.z);
  }
  cam.target.lerp(target, 1 - Math.exp(-12 * dt));
  const desired = cameraDesiredPosition(cam.target);
  camera.position.lerp(desired, 1 - Math.exp(-15 * dt));
  if (cam.shake > 0.001) {
    camera.position.x += rand(-1, 1) * cam.shake * 0.35;
    camera.position.y += rand(-1, 1) * cam.shake * 0.28;
    camera.position.z += rand(-1, 1) * cam.shake * 0.35;
    cam.shake = damp(cam.shake, 0, 7, dt);
  }
  camera.lookAt(cam.target.x, cam.target.y + 0.12, cam.target.z);
}

// ─────────────────────────────────────────────────────────────────────────────
//  WORLD QUALITY
// ─────────────────────────────────────────────────────────────────────────────
function applyQuality() {
  if (!renderer) return;
  renderer.setPixelRatio(pixelRatioForQuality());
  renderer.setSize(window.innerWidth, window.innerHeight, false);
  const shadows = ENABLE_SHADOWS && settings.quality !== "low";
  renderer.shadowMap.enabled = shadows;
  if (sunLight) {
    sunLight.castShadow = shadows;
    sunLight.shadow.mapSize.set(shadows ? 1024 : 512, shadows ? 1024 : 512);
  }
  AudioFX.enabled = settings.sound;
}

function initEngine() {
  initRenderer();
  initSky();
  initLights();
  initGround();
  initScenery();
  initPhysics();
  buildPlayer();
  snapCamera();

  window.addEventListener("resize", onResize);
  window.visualViewport?.addEventListener("resize", syncViewport);
  window.visualViewport?.addEventListener("scroll", syncViewport);

  renderer.render(scene, camera);
}

function onResize() {
  if (!renderer) return;
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight, false);
  placeJoystickHome();
  syncViewport();
}

content.text:
Now 04-entities.js: geometry init, build visuals, measure, spawn entity, despawn, recycle, update entities, explosions, particles, muzzle flash, weather, world effects, vehicles, player update maybe in 05.

Let me carefully implement.

Geometry cache initialization:
```js
function initGeometries(){
 GEO.box = new THREE.BoxGeometry(1,1,1);
 GEO.sphere = new THREE.SphereGeometry(0.5, 18, 12);
 GEO.cylinder = new THREE.CylinderGeometry(0.5,0.5,1,16);
 GEO.cone = new THREE.ConeGeometry(0.5,1,16);
 GEO.torus = new THREE.TorusGeometry(0.5,0.12,8,20);
}
```
Torus scale: geometry outer radius .62; scaling 2.5 → outer radius 1.55, diameter 3.1. Good.

`buildVisualsGroup(visuals, group, center=true)`:
```js
group.clear(); // note: Object3D.clear removes children
for v:
 const mesh = new THREE.Mesh(GEO[v.shape]||GEO.box, visualMaterial(v));
 mesh.position.set(...v.position); mesh.rotation.set(deg..); mesh.scale.set(...);
 mesh.castShadow=true; mesh.receiveShadow=true;
 group.add(mesh)
group.updateMatrixWorld(true);
const box = new THREE.Box3().setFromObject(group);
if (box.isEmpty()) box.set(new Vector3(-.5,-.5,-.5), new Vector3(.5,.5,.5));
const centerVec = box.getCenter(new Vector3());
if (center) { for (const child of group.children) child.position.sub(centerVec); }
const size = box.getSize(new Vector3());
group.position.set(0,0,0); group.quaternion.identity(); group.scale.setScalar(1);
return {size: size.max(new Vector3(0.2,0.2,0.2)), center: centerVec};
```
Careful: `size.max` mutates; use `size.set(Math.max(size.x,.2),...)`.
- For torus default geometry: outer radius .62, inner .38; scaling [2.5,2.5,2.5] gives outer 1.55. Good.
- For capsule geometry not used.
- If visuals include a mesh with opacity < 1, castShadow still true; fine.
- Center offset applied to children positions. For nested? children are meshes only. Good.
- group.scale set to 1 before bbox.

`measureVisuals(visuals)`: build temp group, get size, then clear.

`spawnEntity(spec, opts)`:
Parameters:
```
opts = {position, quaternion, velocity, isProjectile, visuals, scale, life, onImpact, action, isWeather, spin, yaw}
```
Need to handle recycling. Check `entities.length >= MAX_BODIES` before creating.

`recycleOldest`:
```js
function recycleOldest(){
 const now = state.time;
 const candidates = entities.filter(e=>!e.dead && e!==state.drivingEntity && !e.protected && now-e.born>0.8);
 candidates.sort((a,b)=>a.born-b.born);
 let target = candidates[0];
 if(!target) target = entities.find(e=>!e.dead && e!==state.drivingEntity);
 if(!target) return false;
 despawnEntity(target);
 if(state.time-state.lastRecycleToast>2.5){ state.lastRecycleToast=state.time; toast('Body limit reached — recycled oldest','warn','♻️',1600); }
 return true;
}
```
For tower spawn, if limit reached, recycle. Good.

`spawnEntity`:
```js
if (entities.length >= MAX_BODIES) recycleOldest();
const group = entityPool.pop() || new THREE.Group();
group.clear(); group.visible=true; group.position.set(0,0,0); group.quaternion.identity(); group.scale.setScalar(1);
const visuals = opts.visuals || spec.visuals;
const built = buildVisualsGroup(visuals, group, true);
let scale = opts.scale ?? 1;
if (!isFinite(scale) || scale <= 0) scale=1;
const size = built.size.clone().multiplyScalar(scale);
group.scale.setScalar(scale);
group.position.copy(position); scene.add(group);
```
Wait: `buildVisualsGroup` centers children and returns bbox size at scale 1. Setting group.scale = scale scales visuals. Body shape uses size*scale. Good.
- But group.scale animation for spawn-in would conflict with base scale. Store `ent.baseScale=scale` and animate from 0.01*scale. We can add spawn animation via `ent.spawnT = 0`; in update, `group.scale.setScalar(scale * easeOutBack(...))`. That changes visual but body already full. Fine.
- For projectiles, no spawn animation (or quick). Use spawnT=1 for projectiles.

Position is a THREE.Vector3. quaternion optional THREE.Quaternion or number yaw. Use:
```js
const q = new THREE.Quaternion();
if (opts.quaternion) q.copy(opts.quaternion); else if (opts.yaw!=null) q.setFromAxisAngle(UP, opts.yaw);
group.quaternion.copy(q);
```
Body:
```js
const mass = isProjectile ? action.projectileMass : spec.physics.mass;
const body = new CANNON.Body({
 mass, material: spec.physics.bouncy ? matBouncy : (spec.type==='vehicle'?matVehicle:matEntity),
 linearDamping: isProjectile ? 0.01 : spec.physics.linearDamping,
 angularDamping: spec.physics.angularDamping,
 fixedRotation: spec.type==='vehicle',
 allowSleep: !isProjectile,
});
```
- For projectiles, mass must be >0; if action.projectileMass missing, .5.
- Collider:
```js
const maxDim = Math.max(size.x,size.y,size.z);
const minDim = Math.min(size.x,size.y,size.z);
let shape;
if (isProjectile) shape = new CANNON.Sphere(clamp(maxDim*0.32,0.18,0.85));
else if (spec.physics.collider==='sphere') shape = new CANNON.Sphere(clamp(maxDim*0.5,0.15,3));
else shape = new CANNON.Box(new CANNON.Vec3(Math.max(size.x/2,.05),...));
body.addShape(shape);
```
For trampoline size x=3, y=.8, z=3 → box half 1.5,.4,1.5. Good.
For vehicle box half; okay.
For bouncy ball size 2 → sphere radius 1. Good.
- body.position set from position; quaternion set.
- collisionFilterGroup/mask.
- velocity set.
- angularVelocity: for projectiles set random spin if opts.spin; else zero.
- add to world.
- collide listener:
```js
if (isProjectile) {
 body.addEventListener("collide", (ev) => {
   if (ent.dead) return;
   const impact = Math.abs(ev.contact ? ev.contact.getImpactVelocityAlongNormal() : 5);
   if (ent.age < 0.06) return;
   handleProjectileImpact(ent, impact);
 });
}
```
- Entity record:
```js
const ent = { id: nextEntityId++, spec, group, body, isProjectile:!!isProjectile, isWeather:!!opts.isWeather, action: opts.action || spec.action_behavior, life: opts.life ?? (isProjectile?7:Infinity), age:0, born:state.time, dead:false, baseScale:scale, spawnT: isProjectile?1:0, onImpact: opts.onImpact || spec.action_behavior.onImpact, protected:false, tag: opts.tag||'' };
body.entity = ent;
```
Cannon Body allows custom props. Good.
- If spec.type==='vehicle', set `ent.vehicle = {yaw: opts.yaw||0, speed:0, maxSpeed:..., ...}`; wheels? collect meshes with tag wheel? Not needed.
- If `opts.isTowerBlock` etc.
- `entities.push(ent)`.
- Update stats maybe throttled; call updateBodyCount immediate.
- For non-projectile, add materialize ring at position (in effects).
- For vehicle, no spawn animation? Yes, nice.
- Return ent.

`updateBodyCount()`: set dom.bodyCount.textContent = entities.length; style.

`despawnEntity(ent, opts)`:
- remove from array.
- if driving, exitVehicle(true).
- if nearVehicle, clear.
- body.removeEventListener? The listener references ent; removing body from world enough.
- scene.remove(group); group.clear(); group.visible=false; entityPool push if <100.
- if ent.weapon? no.
- `ent.dead=true`.
- update body count.
- if opts.poof and position → small poof burst.

`handleProjectileImpact(ent, impact)`:
- If `ent.onImpact==='explode'`:
  - `ent.dead=true;` but don't despawn before explosion? Call explodeAt at body position with action; then despawnEntity(ent). Need avoid double. Set ent.dead true then call despawnEntity; despawn checks dead? Currently if ent.dead return; so call explosion then despawn without setting dead, or set a flag. Use `if (ent.impacted) return; ent.impacted=true;` then explode, despawn.
- If 'bounce': AudioFX.bounce(); body.material? Already bouncy? Projectiles use matEntity with restitution .22, not bouncy. For bounce projectiles, set body.material=matBouncy at spawn if onImpact==='bounce'. Do that.
- If 'stick': body.velocity.setZero(); body.angularVelocity.setZero(); body.mass=0; body.type=CANNON.Body.STATIC; body.updateMassProperties(); body.allowSleep=true; ent.life=6; AudioFX.land();
- If 'none': no effect.
- Impact threshold: only explode if impact > 1.2, but spawn may touch ground? Projectiles spawn at chest height, no. Use if impact < 1 and age<.2 return. Fine.

`explodeAt(pos, radius, force, color)`:
- pos can be CANNON.Vec3 or THREE.Vector3. Convert.
- Loop entities: skip dead, skip self? The exploding entity still in list; skip if `ent.isExplodingSource` or just call after removing? We can despawn first then explode to avoid self. In handleImpact: save pos, despawnEntity(ent), then explodeAt. That works. Do that.
- Apply impulses to bodies. Use `body.applyImpulse(new CANNON.Vec3(...))`. For sleeping bodies, wakeUp.
- Player impulse if not driving and distance < radius.
- Effect visuals.
- Sound, shake, vibrate.
- Scorch.
- If explosion near weather? no.
- Chain reactions: other projectiles nearby will get impulses; their collision triggers explosions. Could cause chain. Fine.

`applyImpulse` magnitude: 
```js
const strength = force * falloff * ent.body.mass * 0.55;
body.applyImpulse(dir.scale(strength), body.position?) 
```
Cannon `applyImpulse(impulse, relativePoint)`; default relative point zero (center). Use `body.applyImpulse(new CANNON.Vec3(dir.x*strength, (dir.y+0.55)*strength, dir.z*strength))`.
For player mass 70, force 12, falloff .8 → 12*.8*70*.55=369 impulse → 5.3 m/s. Good.
- Add upward bias.

Particles:
Global arrays:
```js
let bursts=[], shockwaves=[], flashes=[], scorches=[];
```
`initEffects()` creates:
- 5 bursts: Points with 64 vertices, PointsMaterial map glowTexture, size .5, transparent, depthWrite false, blending Additive, vertexColors? Use per-burst color. `pts.visible=false`.
- 4 shockwaves: RingGeometry(0.82,1,48) rotated -PI/2, MeshBasicMaterial({color, transparent, opacity, side:DoubleSide, blending:Additive, depthWrite:false}). Add scene.
- 6 flashes: Sprite with glow texture additive.
- 10 scorches: CircleGeometry(1,24) rotated -PI/2, MeshBasicMaterial black transparent .22, depthWrite false, polygonOffset. Add.
- `spawnBurst(pos,color,radius,count=60)`: find inactive, reset life, positions random, velocities random sphere * speed (radius*2), color.
- `updateEffects(dt)`: for each burst: life -= dt; positions += vel*dt; vel.y -= 9*dt; drag; opacity = life/max; needsUpdate; hide when done.
- shockwave: life; scale = lerp(0.6, radius, 1-life/max); opacity = life/max*.8.
- flashes: life .08; scale .6; hide.
- scorches: fade over 7s; hide. Limit.
- muzzleFlash(pos,color): use flash pool, set position, scale .7, life .09.
- materialize ring at spawn: use shockwave pool with small radius and cyan color, or a ring mesh. Use shockwave with radius 1.5, life .5, color #6ee7c8, plus burst count 14. Nice.
- explosion also spawns debris? no.

- `updateEffects` must handle pooled objects with `maxLife`.

Weather:
```js
function startWeather(kind, spec, eff){
 stopWeather();
 if(kind==='rain') createRain();
 if(kind==='meteor') state.weather = {kind, spec, rate: eff.weatherRate, spawnTimer:0, maxActive: 6, until: state.time+eff.duration};
}
```
But applyWorldEffect sets state.weather. Let's design:
- `state.weather = {kind, until, rate, spawnTimer, spec, projectileVisuals, action}`.
- `startWeather(kind, spec, duration)` handles rain creation/removal.
- `stopWeather()` removes rain, state.weather=null.
- `updateWeather(dt)`:
  - if !state.weather return.
  - if state.time > state.weather.until → stopWeather(); return.
  - rain: update points.
  - meteor: spawn timer; count active weather entities; if < 6 spawn.
- `createRain()`: N=520. positions random around player ±28, y 0..24. Store speed. Points with color #bfe4ff, size .075, transparent .7. `rainSystem={points, speeds, count}`. Add to scene.
  - update: for each, y -= speed*dt; x += wind*dt; if y<0 or distance > 40: reset y=rand(14,26), x/z around player. Set position attr needsUpdate. Move points object with player? Positions are world; reset around player.
- `spawnMeteor()`:
  - pos around player at radius 6..16, y=24.
  - velocity downward + toward player slightly.
  - visuals = state.weather.projectileVisuals?.length ? ... : fireballVisuals();
  - spawnEntity(spec, {position, velocity, isProjectile:true, visuals, action: state.weather.action || spec.action_behavior, life:12, isWeather:true, scale: 1.2, spin: ...});
  - Note spec.type world_event, physics mass maybe 4. spawnEntity for projectile uses action.projectileMass (default .5). Good.
  - For meteors, onImpact explode. `action` from spec.action_behavior; onImpact default explode.
  - Set `ent.weather = true`.
- Rain should not count bodies. Fine.

`stopWeather` also remove rain.
- When world effect ends, `endWorldEffect()`.

Sky:
`setSkyTarget(hexTop, mode)`:
```js
const top = new THREE.Color(hex);
const horizon = top.clone().lerp(new THREE.Color('#ffffff'), 0.62);
skyTarget.top.copy(top); skyTarget.horizon.copy(horizon); skyTarget.fog.copy(horizon).lerp(new THREE.Color('#dfe9e0'), .25);
skyTarget.sun = mode==='dark'?0.9:2.35; skyTarget.hemi=...;
```
- Default sky top #3f9dfb.
- For low gravity #6ea8ff.
- Rain #74879b.
- Meteor #b96a4e? top maybe #5b4a7a, horizon #ffb27a. Use skyColor given #ff9a6b; top should be deeper: `top = color.clone().multiplyScalar(.7)`? Use hex given as top and horizon light. For #ff9a6b, horizon very light peach, sky peachy. Fine.
- Night? not used.

`updateSky(dt)`:
- lerp uniforms to target: `skyUniforms.topColor.value.lerp(skyTarget.top, 1-exp(-2.5dt))`.
- scene.fog.color.lerp(skyTarget.fog, ...); 
- sunLight.intensity = damp(...); hemiLight.intensity = damp(...).
- clouds drift.
- dust rotate.

World effect:
```js
function applyWorldEffect(spec){
 const eff = spec.world_effect;
 state.gravityTarget = eff.gravity;
 const duration = eff.duration;
 state.effect = {name:spec.name, until: state.time+duration, duration, spec, icon: ...};
 if(eff.weather && eff.weather!=='none'){ startWeather(eff.weather, spec, duration); }
 else stopWeather();
 // sky
 let sky = eff.skyColor;
 if(!sky && eff.weather==='rain') sky='#74879b';
 if(!sky && eff.weather==='meteor') sky='#ff9a6b';
 if(sky) setSkyTarget(sky, eff.weather==='meteor'?'warm':'normal');
 else setSkyDefault();
 setEffectChip(spec.name, duration, icon);
 if(eff.gravity<0.6) toast('Gravity lowered — jump around!', ...)? Maybe.
}
```
- If world event has no weather and no gravity change? still timer.
- `endWorldEffect()`: state.effect=null; gravityTarget=1; stopWeather(); setSkyDefault(); hideEffectChip().
- For low gravity, sky color set. Good.
- When new world event starts, old effect replaced.
- If world event is "rain" with gravity 1, sky grey.

`updateWorldEffect(dt)`:
- world.gravity.y = damp(world.gravity.y, BASE_GRAVITY * state.gravityTarget, 3, dt). But state.gravityTarget=0 → 0.
- if effect and time>until → end.
- update chip every frame? `setEffectChip` creates text updates; okay at 4Hz. Use HUD update.
- `setEffectChip(state.effect.name, remaining, icon)` in updateHUD.

`setSkyDefault` resets target top #3f9dfb, horizon #dff2ff, fog #cfe6f5, sun 2.35, hemi 1.15.

Vehicle functions in 04 or 05? Let's put spawnVehicle, enter/exit, updateVehicles in 04. Player update in 05.

`spawnVehicle(spec, position, yaw)`:
- compute size via measureVisuals; y = max(size.y/2 + 0.18, .5).
- spawnEntity with type vehicle.
- ent.vehicle = {yaw, speed:0,...}.
- body.quaternion setFromAxisAngle(UP,yaw).
- position.y should be ground + size/2. Since group centered, bottom at pos.y-size.y/2. Good.
- `ent.protected=true`? Vehicles shouldn't be recycled instantly; but limit. Keep protected true for 8s? Add `protectedUntil = state.time+6`.
- `state.nearVehicle = ent`; show hint? Only if not driving.
- Return ent.

`enterVehicle(ent)`:
- if state.drivingEntity return.
- state.drivingEntity=ent; state.nearVehicle=null; vehicleHint off.
- playerGroup.visible=false; blobShadow.visible=false; playerBody.collisionResponse=false; playerBody.velocity.setZero(); playerBody.angularVelocity.setZero(); playerBody.sleep();
- cam.dist=10.5; cam.lastLook=-99; state.equipped? Keep weapon spec but reticle off.
- setUseLabel('EXIT'); jumpBtn label 'BOOST'; useBtn icon? Could change icon to exit door? Keep.
- dom.vehicleHint off.
- setItemCard(ent.spec, 'DRIVING · USE TO EXIT').
- toast('Driving '+name+' — USE to exit','good','🚙').
- AudioFX.ui.
- `cam.yaw = ent.vehicle.yaw` maybe.

`exitVehicle(force=false)`:
- ent = state.drivingEntity; if none return.
- compute side position:
```js
const right = new THREE.Vector3(1,0,0).applyAxisAngle(UP, ent.vehicle.yaw);
const p = ent.body.position; const pos = new THREE.Vector3(p.x+right.x*2.4, p.y+1.1, p.z+right.z*2.4);
```
- playerBody.collisionResponse=true; playerBody.wakeUp(); playerBody.position.set(pos.x, Math.max(1.1,pos.y), pos.z); velocity zero; playerGroup.visible=true; blobShadow.visible=true.
- state.drivingEntity=null; cam.dist=6.7; setUseLabel based on equipped; jump label JUMP; update item card.
