// ─────────────────────────────────────────────────────────────────────────────
//  PLAYER MOVEMENT + ANIMATION
// ─────────────────────────────────────────────────────────────────────────────
const rayFrom = new CANNON.Vec3();
const rayTo = new CANNON.Vec3();
const rayResult = new CANNON.RaycastResult();

function updatePlayer(dt) {
  if (!playerBody) return;
  if (state.drivingEntity) return;

  const b = playerBody;
  rayFrom.set(b.position.x, b.position.y, b.position.z);
  rayTo.set(b.position.x, b.position.y - 0.92, b.position.z);
  rayResult.reset();
  world.raycastClosest(rayFrom, rayTo, {
    collisionFilterMask: G_GROUND | G_ENTITY | G_VEHICLE,
    skipBackfaces: true,
  }, rayResult);
  const grounded = rayResult.hasHit && rayResult.distance <= PLAYER_RADIUS + 0.19;
  state.grounded = grounded;
  state.coyote = grounded ? 0.12 : Math.max(0, state.coyote - dt);

  state.jumpBuffer = Math.max(0, state.jumpBuffer - dt);
  state.jumpCooldown = Math.max(0, state.jumpCooldown - dt);
  state.boostCooldown = Math.max(0, state.boostCooldown - dt);

  if (state.jumpBuffer > 0 && state.coyote > 0 && state.jumpCooldown <= 0) {
    b.velocity.y = 8.4;
    b.wakeUp();
    state.jumpBuffer = 0;
    state.coyote = 0;
    state.jumpCooldown = 0.22;
    state.squash = 0.14;
    state.wasGrounded = false;
    AudioFX.jump();
    buzz(8);
  }

  let mx = clamp(input.moveX + (keys.d ? 1 : 0) - (keys.a ? 1 : 0), -1, 1);
  let my = clamp(input.moveY + (keys.w ? 1 : 0) - (keys.s ? 1 : 0), -1, 1);
  if (state.paused) { mx = 0; my = 0; }
  const mag = Math.min(1, Math.hypot(mx, my));

  const forward = new THREE.Vector3(-Math.sin(cam.yaw), 0, -Math.cos(cam.yaw));
  const right = new THREE.Vector3(Math.cos(cam.yaw), 0, -Math.sin(cam.yaw));
  const wish = forward.multiplyScalar(my).add(right.multiplyScalar(mx));
  if (wish.lengthSq() > 1) wish.normalize();

  const targetX = wish.x * PLAYER_SPEED * mag;
  const targetZ = wish.z * PLAYER_SPEED * mag;
  const accel = grounded ? 17 : 4.2;
  b.velocity.x = damp(b.velocity.x, targetX, accel, dt);
  b.velocity.z = damp(b.velocity.z, targetZ, accel, dt);

  // Landing detection
  if (!grounded) state.fallSpeed = Math.min(state.fallSpeed, b.velocity.y);
  if (!state.wasGrounded && grounded) {
    if (state.fallSpeed < -6.5) {
      state.squash = 0.17;
      AudioFX.land();
      buzz(6);
    }
    state.fallSpeed = 0;
  }
  state.wasGrounded = grounded;

  // Sync the visual rig
  playerGroup.position.set(b.position.x, b.position.y - PLAYER_RADIUS, b.position.z);
  const horizSpeed = Math.hypot(b.velocity.x, b.velocity.z);
  const moving = horizSpeed > 0.35;
  let targetYaw = playerGroup.rotation.y;
  if (state.time < state.aimingUntil) targetYaw = cam.yaw;
  else if (moving) targetYaw = Math.atan2(-b.velocity.x, -b.velocity.z);
  playerGroup.rotation.y = angleDamp(playerGroup.rotation.y, targetYaw, 13, dt);

  const sf = clamp(horizSpeed / PLAYER_SPEED, 0, 1);
  state.walkPhase += dt * (3.2 + horizSpeed * 1.35);
  const swing = Math.sin(state.walkPhase * 2.1) * 0.58 * sf;
  const legL = playerVisual.userData.legL;
  const legR = playerVisual.userData.legR;
  const armL = playerVisual.userData.armL;
  const armR = playerVisual.userData.armR;
  if (legL) legL.rotation.x = damp(legL.rotation.x, swing, 16, dt);
  if (legR) legR.rotation.x = damp(legR.rotation.x, -swing, 16, dt);

  const aiming = state.equipped && state.equipped.type === "weapon";
  if (aiming) {
    if (armR) {
      armR.rotation.x = damp(armR.rotation.x, -1.38 + state.recoil * 0.18, 14, dt);
      armR.rotation.z = damp(armR.rotation.z, -0.1, 14, dt);
    }
    if (armL) {
      armL.rotation.x = damp(armL.rotation.x, -0.92, 14, dt);
      armL.rotation.z = damp(armL.rotation.z, 0.36, 14, dt);
    }
  } else {
    if (armL) {
      armL.rotation.x = damp(armL.rotation.x, -swing * 0.85, 14, dt);
      armL.rotation.z = damp(armL.rotation.z, 0.08, 14, dt);
    }
    if (armR) {
      armR.rotation.x = damp(armR.rotation.x, swing * 0.85, 14, dt);
      armR.rotation.z = damp(armR.rotation.z, -0.08, 14, dt);
    }
  }

  state.squash = damp(state.squash, 0, 9, dt);
  const bob = grounded ? Math.abs(Math.sin(state.walkPhase * 2.1)) * 0.035 * sf : 0;
  playerVisual.position.y = damp(playerVisual.position.y, bob - state.squash * 0.18, 14, dt);
  playerVisual.scale.set(1 - state.squash * 0.35, 1 + state.squash, 1 - state.squash * 0.35);

  // Weapon pop-in, recoil and idle sway
  if (weaponMount) {
    const base = weaponMount.userData.base;
    weaponMount.scale.setScalar(damp(weaponMount.scale.x, 1, 14, dt));
    state.recoil = damp(state.recoil, 0, 12, dt);
    weaponMount.position.z = base.z + state.recoil * 0.16;
    weaponMount.position.y = base.y + Math.sin(state.walkPhase * 2.1) * 0.012 * sf - state.recoil * 0.025;
    weaponMount.rotation.x = -state.recoil * 0.3;
  }

  // Contact shadow follows, fading with height
  if (blobShadow) {
    blobShadow.position.set(b.position.x, 0.06, b.position.z);
    const h = Math.max(0, b.position.y - PLAYER_RADIUS);
    const k = clamp(1 - h * 0.07, 0.45, 1);
    blobShadow.scale.setScalar(k);
    blobShadow.material.opacity = 0.17 * k;
  }

  if (b.position.y < state.deathY) respawnPlayer(true);
}

// ─────────────────────────────────────────────────────────────────────────────
//  WEAPONS
// ─────────────────────────────────────────────────────────────────────────────
function defaultProjectileVisuals(spec) {
  const color = (spec.visuals && spec.visuals[0] && spec.visuals[0].color) || "#ffd166";
  return orbVisuals(color);
}

function equipWeapon(spec) {
  state.equipped = spec;
  state.lastCreated = spec;
  state.cooldownTotal = Math.max(0.15, spec.action_behavior.cooldown || 0.4);
  state.nextFire = state.time + 0.12;
  if (!weaponMount) return;
  weaponMount.clear();
  const group = new THREE.Group();
  const built = buildVisualsGroup(spec.visuals, group, true);
  const maxDim = Math.max(built.size.x, built.size.y, built.size.z);
  let s = 1;
  if (maxDim > 1.32) s = 1.32 / maxDim;
  else if (maxDim < 0.52) s = Math.min(2.1, 0.52 / Math.max(0.08, maxDim));
  group.scale.setScalar(s);
  group.rotation.y = 0.035;
  weaponMount.add(group);
  heldGroup = group;
  weaponMount.scale.setScalar(0.35);
  setItemCard(spec, "FIRE · " + String(spec.action_behavior.projectile || "PROJECTILE").toUpperCase());
  setUseLabel("FIRE");
  setUseBadge(null);
  dom.reticle.classList.add("on");
  AudioFX.forge();
}

function clearWeapon() {
  if (weaponMount) weaponMount.clear();
  heldGroup = null;
  state.equipped = null;
  dom.reticle.classList.remove("on");
  setUseLabel("USE");
  hideItemCard();
}

function fireWeapon(spec) {
  if (!spec || state.time < state.nextFire) return;
  const action = spec.action_behavior;
  state.cooldownTotal = Math.max(0.12, action.cooldown);
  state.nextFire = state.time + state.cooldownTotal;
  state.aimingUntil = state.time + 1.15;
  state.recoil = 1;
  AudioFX.shoot();
  buzz(9);

  const origin = new THREE.Vector3(playerBody.position.x, playerBody.position.y + 0.92, playerBody.position.z);
  const dir = new THREE.Vector3(
    -Math.sin(cam.yaw),
    clamp(0.16 - cam.pitch * 0.55, -0.45, 0.3),
    -Math.cos(cam.yaw)
  ).normalize();
  const right = new THREE.Vector3(Math.cos(cam.yaw), 0, -Math.sin(cam.yaw));
  origin.addScaledVector(right, 0.32).addScaledVector(dir, 0.7);

  const visuals = spec.projectile_visuals && spec.projectile_visuals.length
    ? spec.projectile_visuals
    : defaultProjectileVisuals(spec);

  const count = clamp(Math.round(action.spawnCount || 1), 1, 4);
  for (let i = 0; i < count; i++) {
    const spread = action.spread || 0;
    const d = dir.clone().add(new THREE.Vector3(
      rand(-spread, spread), rand(-spread, spread), rand(-spread, spread)
    )).normalize();
    spawnEntity(spec, {
      position: origin.clone().add(new THREE.Vector3(rand(-0.06, 0.06), rand(-0.06, 0.06), rand(-0.06, 0.06))),
      velocity: d.multiplyScalar(action.speed || 40),
      isProjectile: true,
      visuals,
      action,
      life: 8,
      scale: action.projectileScale || 1,
      onImpact: action.onImpact,
    });
  }

  const muzzle = origin.clone().addScaledVector(dir, 0.35);
  muzzleFlash(muzzle, "#ffe0a0");
  spawnBurst(muzzle, "#ffe0a0", 0.7, 10);
  dom.reticle.classList.remove("pulse");
  void dom.reticle.offsetWidth;
  dom.reticle.classList.add("pulse");
  dom.useBtn.classList.remove("ready");
}

// ─────────────────────────────────────────────────────────────────────────────
//  OBJECT DEPLOYMENT + TOWERS
// ─────────────────────────────────────────────────────────────────────────────
function spawnPhysicsObject(spec) {
  const forward = new THREE.Vector3(-Math.sin(cam.yaw), 0, -Math.cos(cam.yaw));
  const base = new THREE.Vector3(
    playerBody.position.x + forward.x * 5.0,
    0,
    playerBody.position.z + forward.z * 5.0
  );
  if (spec.structure === "tower") {
    spawnTower(spec, base);
    return null;
  }
  const size = measureVisuals(spec.visuals);
  const y = Math.max(size.y / 2 + 0.14, 0.32);
  const velocity = forward.clone().multiplyScalar(spec.physics.bouncy ? 2.4 : 0.35);
  return spawnEntity(spec, {
    position: new THREE.Vector3(base.x, y, base.z),
    yaw: cam.yaw + rand(-0.16, 0.16),
    velocity,
  });
}

function spawnTower(spec, base) {
  const count = clamp(spec.structureCount || 8, 2, 12);
  const size = measureVisuals(spec.visuals);
  const blockH = Math.max(0.3, size.y * 1.015);
  const palette = ["#ffd166", "#ff8a4c", "#7dd3fc", "#6ee7c8", "#c084fc", "#ff5c8a"];
  for (let i = 0; i < count; i++) {
    const blockSpec = {
      ...spec,
      visuals: spec.visuals.map((v) => ({ ...v })),
      physics: { ...spec.physics },
      action_behavior: { ...spec.action_behavior },
      structure: null,
    };
    blockSpec.visuals[0].color = palette[i % palette.length];
    if (blockSpec.visuals[1]) blockSpec.visuals[1].emissive = palette[i % palette.length];
    spawnEntity(blockSpec, {
      position: new THREE.Vector3(
        base.x + Math.sin(i * 0.8) * 0.045,
        blockH / 2 + i * blockH * 1.005,
        base.z + Math.cos(i * 0.7) * 0.045
      ),
      yaw: (i % 2 ? 1 : -1) * 0.055,
      silent: i > 0,
    });
  }
  spawnShockwave(base, 3.4, "#ffd166", 0.6);
  spawnBurst(new THREE.Vector3(base.x, 0.4, base.z), "#ffd166", 2.4, 26);
  AudioFX.forge();
}

function deployObject(spec) {
  if (state.time < state.nextFire) return;
  const action = spec.action_behavior;
  state.cooldownTotal = Math.max(0.3, action.cooldown || 1);
  state.nextFire = state.time + state.cooldownTotal;
  spawnPhysicsObject(spec);
  AudioFX.forge();
  buzz(10);
}

function deployVehicle(spec) {
  if (state.time < state.nextFire) return;
  state.nextFire = state.time + 2.2;
  const forward = new THREE.Vector3(-Math.sin(cam.yaw), 0, -Math.cos(cam.yaw));
  const base = new THREE.Vector3(
    playerBody.position.x + forward.x * 5.5,
    0,
    playerBody.position.z + forward.z * 5.5
  );
  const ent = spawnVehicle(spec, base, cam.yaw);
  setTimeout(() => {
    if (!ent.dead && !state.drivingEntity && !state.paused) enterVehicle(ent);
  }, 500);
}

// ─────────────────────────────────────────────────────────────────────────────
//  USE / FIRE / KICK
// ─────────────────────────────────────────────────────────────────────────────
function kickNearby() {
  const origin = new THREE.Vector3(playerBody.position.x, playerBody.position.y + 0.55, playerBody.position.z);
  const dir = new THREE.Vector3(-Math.sin(cam.yaw), 0, -Math.cos(cam.yaw));
  let best = null;
  let bestScore = -Infinity;
  for (const ent of entities) {
    if (ent.dead) continue;
    const dx = ent.body.position.x - origin.x;
    const dy = ent.body.position.y - origin.y;
    const dz = ent.body.position.z - origin.z;
    const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
    if (dist > 5.2 || dist < 0.01) continue;
    const dot = (dx * dir.x + dz * dir.z) / Math.max(0.001, Math.hypot(dx, dz));
    if (dot < 0.1) continue;
    const score = dot * 2 - dist * 0.12;
    if (score > bestScore) { bestScore = score; best = ent; }
  }
  if (best) {
    const strength = Math.min(46, 8 + best.body.mass * 2.2);
    best.body.wakeUp();
    best.body.applyImpulse(new CANNON.Vec3(dir.x * strength, strength * 0.5, dir.z * strength));
    spawnBurst(new THREE.Vector3(best.body.position.x, best.body.position.y, best.body.position.z), "#ffffff", 0.7, 12);
    AudioFX.land();
    buzz(10);
  } else {
    toast("Nothing to use — tap ✦ Create", "", "✦", 1700);
    AudioFX.ui();
  }
}

function useAction() {
  if (!state.ready || state.paused) return;
  AudioFX.init();
  if (state.drivingEntity) { exitVehicle(); return; }
  if (state.nearVehicle) { enterVehicle(state.nearVehicle); return; }
  const spec = state.equipped;
  if (!spec) { kickNearby(); return; }
  if (spec.type === "weapon") fireWeapon(spec);
  else if (spec.type === "physics_object") deployObject(spec);
  else if (spec.type === "vehicle") deployVehicle(spec);
  else if (spec.type === "world_event") applyWorldEffect(spec);
}

function requestJump() {
  AudioFX.init();
  if (state.drivingEntity) {
    const v = state.drivingEntity.vehicle;
    if (v && state.boostCooldown <= 0) {
      v.boost = 1;
      state.boostCooldown = 1.5;
      AudioFX.boost();
      buzz(20);
      cam.shake = Math.min(0.5, cam.shake + 0.18);
    }
    return;
  }
  if (state.paused) return;
  state.jumpBuffer = 0.17;
}

// ─────────────────────────────────────────────────────────────────────────────
//  CREATE FLOW (AI or local forge -> world)
// ─────────────────────────────────────────────────────────────────────────────
async function createFromPrompt(prompt) {
  prompt = String(prompt || "").trim();
  if (!prompt) { toast("Type something first", "warn", "✍️", 1600); return; }
  if (state.creating) { toast("Still materializing…", "warn", "⏳", 1500); return; }
  state.lastPrompt = prompt;
  state.creating = true;
  hideHint();
  setMaterializing(true);
  AudioFX.init();
  AudioFX.materialize();
  const started = performance.now();
  let spec = null;
  let usedAI = false;
  let aiError = null;
  try {
    if ((settings.key || "").trim()) {
      usedAI = true;
      spec = await requestAICreation(prompt);
    } else {
      spec = localForge(prompt);
    }
  } catch (err) {
    aiError = err;
    console.warn("[Reality Forge] AI request failed; using local forge.", err);
  }
  const elapsed = performance.now() - started;
  if (elapsed < 560) await wait(560 - elapsed);
  if (!spec) {
    spec = localForge(prompt);
    if (usedAI) toast("AI hiccup — local forge took over", "warn", "⚡", 3200);
  }
  if (spec) {
    applySpec(spec, prompt);
    if (!usedAI && state.firstCreation) {
      state.firstCreation = false;
      setTimeout(() => toast("Local forge mode — add a key for anything", "", "🔑", 3000), 700);
    }
  }
  if (aiError && !spec) toast("Forge failed — try again", "warn", "⚠️", 2600);
  state.creating = false;
  setMaterializing(false);
}

function applySpec(spec, prompt) {
  if (!spec) return;
  state.lastCreated = spec;
  hideHint();
  const forward = new THREE.Vector3(-Math.sin(cam.yaw), 0, -Math.cos(cam.yaw));
  const base = new THREE.Vector3(
    playerBody.position.x + forward.x * 5.5,
    0,
    playerBody.position.z + forward.z * 5.5
  );

  if (spec.type === "weapon") {
    equipWeapon(spec);
    toast("Forged " + spec.name, "good", "✦", 2400);
  } else if (spec.type === "vehicle") {
    state.equipped = spec;
    state.nextFire = state.time + 2.2;
    const ent = spawnVehicle(spec, base, cam.yaw);
    setItemCard(spec, "TAP USE TO DRIVE");
    setUseLabel("DRIVE");
    dom.reticle.classList.remove("on");
    toast("Forged " + spec.name, "good", "🚙", 2200);
    setTimeout(() => {
      if (!ent.dead && !state.drivingEntity && !state.paused) enterVehicle(ent);
    }, 700);
  } else if (spec.type === "physics_object") {
    state.equipped = spec;
    state.nextFire = state.time + 0.9;
    state.cooldownTotal = Math.max(0.4, spec.action_behavior.cooldown || 1);
    spawnPhysicsObject(spec);
    setItemCard(spec, "DEPLOY");
    setUseLabel("DEPLOY");
    dom.reticle.classList.remove("on");
    toast("Forged " + spec.name, "good", "🧱", 2200);
  } else {
    applyWorldEffect(spec);
  }
  updateBodyCount();
}

function respawnPlayer(silent = false) {
  if (state.drivingEntity) exitVehicle(true);
  playerBody.collisionResponse = true;
  playerBody.wakeUp();
  playerBody.position.set(0, 1.2, 0);
  playerBody.velocity.setZero();
  playerBody.angularVelocity.setZero();
  playerGroup.visible = true;
  playerGroup.position.set(0, 0.75, 0);
  playerGroup.rotation.y = 0;
  blobShadow.visible = true;
  state.fallSpeed = 0;
  state.jumpBuffer = 0;
  state.wasGrounded = false;
  cam.target.set(0, 1.35, 0);
  snapCamera();
  if (!silent) toast("Back at the forge", "", "✦", 1600);
}

function clearCreations() {
  if (state.drivingEntity) exitVehicle(true);
  [...entities].forEach((ent) => despawnEntity(ent));
  clearWeapon();
  state.equipped = null;
  state.nextFire = 0;
  state.effect = null;
  state.gravityTarget = 1;
  stopWeather();
  setSkyDefault();
  hideEffectChip();
  hideItemCard();
  setUseLabel("USE");
  updateBodyCount();
  toast("World cleared", "", "🧹", 1800);
}

// ─────────────────────────────────────────────────────────────────────────────
//  OVERLAYS: CREATE SHEET + SETTINGS
// ─────────────────────────────────────────────────────────────────────────────
let draftProvider = settings.provider;
let recognition = null;
let listening = false;

function updateEngineNote() {
  const key = (settings.key || "").trim();
  if (key) {
    dom.engineNote.textContent = "Connected to " + (settings.provider === "openai" ? "OpenAI" : "Gemini") + " · " + activeModel();
  } else {
    dom.engineNote.textContent = "Local forge ready — add a key in settings for unlimited creations";
  }
}

function openPrompt() {
  if (state.creating) { toast("Still materializing…", "warn", "⏳", 1500); return; }
  if (dom.settingsOverlay.classList.contains("open")) closeSettings();
  AudioFX.init();
  AudioFX.ui();
  state.paused = true;
  resetJoystick();
  hideHint();
  dom.promptOverlay.classList.add("open");
  dom.promptOverlay.setAttribute("aria-hidden", "false");
  dom.promptOverlay.style.top = "";
  dom.promptOverlay.style.height = "";
  updateEngineNote();
  syncViewport();
  setTimeout(() => {
    try { dom.promptInput.focus({ preventScroll: true }); } catch { dom.promptInput.focus(); }
  }, 230);
}

function closePrompt() {
  if (!dom.promptOverlay.classList.contains("open")) return;
  stopVoice();
  dom.promptOverlay.classList.remove("open");
  dom.promptOverlay.setAttribute("aria-hidden", "true");
  dom.promptOverlay.style.top = "";
  dom.promptOverlay.style.height = "";
  dom.promptInput.blur();
  dom.voiceStatus.classList.remove("on");
  state.paused = false;
}

function sendPrompt() {
  const text = dom.promptInput.value.trim();
  if (!text) {
    toast("Type something first", "warn", "✍️", 1600);
    try { dom.promptInput.focus(); } catch { /* ignore */ }
    return;
  }
  state.lastPrompt = text;
  dom.promptInput.value = "";
  dom.promptInput.style.height = "auto";
  closePrompt();
  createFromPrompt(text);
}

function openSettings() {
  if (dom.promptOverlay.classList.contains("open")) closePrompt();
  AudioFX.init();
  AudioFX.ui();
  state.paused = true;
  resetJoystick();
  draftProvider = settings.provider;
  refreshSettingsUI();
  dom.settingsOverlay.classList.add("open");
  dom.settingsOverlay.setAttribute("aria-hidden", "false");
  dom.settingsOverlay.style.top = "";
  dom.settingsOverlay.style.height = "";
  syncViewport();
}

function closeSettings() {
  if (!dom.settingsOverlay.classList.contains("open")) return;
  dom.settingsOverlay.classList.remove("open");
  dom.settingsOverlay.setAttribute("aria-hidden", "true");
  dom.settingsOverlay.style.top = "";
  dom.settingsOverlay.style.height = "";
  state.paused = false;
}

function refreshSettingsUI() {
  if (!dom.providerSeg) return;
  [...dom.providerSeg.querySelectorAll("button")].forEach((b) => {
    b.classList.toggle("on", b.dataset.provider === draftProvider);
  });
  dom.modelInput.placeholder = defaultModel(draftProvider);
  dom.keyInput.value = settings.key || "";
  dom.keyInput.type = "password";
  dom.eyeBtn.textContent = "SHOW";
  dom.modelInput.value = settings.model || "";
  dom.soundToggle.classList.toggle("on", settings.sound);
  dom.soundToggle.setAttribute("aria-checked", String(settings.sound));
  dom.qualitySelect.value = settings.quality;
}

function saveSettingsFromUI() {
  let key = (dom.keyInput.value || "").trim();
  const model = (dom.modelInput.value || "").trim();
  let provider = draftProvider;
  if (key.startsWith("AIza") && provider === "openai") {
    provider = "gemini";
    toast("Detected a Gemini key — provider switched", "", "🔑", 2600);
  } else if (key.startsWith("sk-") && provider === "gemini") {
    provider = "openai";
    toast("Detected an OpenAI key — provider switched", "", "🔑", 2600);
  }
  settings.provider = provider;
  settings.key = key;
  settings.model = model;
  settings.sound = dom.soundToggle.classList.contains("on");
  settings.quality = dom.qualitySelect.value;
  persistSettings();
  AudioFX.enabled = settings.sound;
  applyQuality();
  updateEngineNote();
  closeSettings();
  if (key) toast("AI connected · " + activeModel(), "good", "⚡", 2600);
  else toast("Local forge mode enabled", "", "🧠", 2200);
  AudioFX.ui();
}

function closeAll() {
  closePrompt();
  closeSettings();
}

// ─────────────────────────────────────────────────────────────────────────────
//  VOICE-TO-TEXT (Web Speech API)
// ─────────────────────────────────────────────────────────────────────────────
function setupVoice() {
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SR) {
    dom.micBtn.style.opacity = "0.42";
    dom.micBtn.setAttribute("aria-label", "Voice input not supported in this browser");
    dom.micBtn.addEventListener("click", () => {
      toast("Voice input is not supported in this browser", "warn", "🎙️", 2600);
    });
    return;
  }
  recognition = new SR();
  recognition.lang = navigator.language || "en-US";
  recognition.interimResults = true;
  recognition.continuous = false;
  recognition.maxAlternatives = 1;

  recognition.onresult = (event) => {
    let text = "";
    for (let i = event.resultIndex; i < event.results.length; i++) {
      text += event.results[i][0].transcript;
    }
    dom.promptInput.value = text.trim();
    dom.promptInput.style.height = "auto";
    dom.promptInput.style.height = Math.min(128, dom.promptInput.scrollHeight) + "px";
    dom.voiceStatus.textContent = "🎙 " + text.trim();
    dom.voiceStatus.classList.add("on");
  };
  recognition.onerror = (event) => {
    listening = false;
    dom.micBtn.classList.remove("listening");
    dom.voiceStatus.classList.remove("on");
    if (event.error !== "aborted" && event.error !== "no-speech") {
      toast("Voice unavailable: " + event.error, "warn", "🎙️", 2600);
    }
  };
  recognition.onend = () => {
    listening = false;
    dom.micBtn.classList.remove("listening");
    dom.voiceStatus.classList.remove("on");
  };

  dom.micBtn.addEventListener("click", () => {
    if (!dom.promptOverlay.classList.contains("open")) return;
    AudioFX.init();
    if (listening) {
      stopVoice();
      return;
    }
    try {
      recognition.start();
      listening = true;
      dom.micBtn.classList.add("listening");
      dom.voiceStatus.textContent = "🎙 Listening… speak your creation";
      dom.voiceStatus.classList.add("on");
      buzz(8);
    } catch {
      toast("Could not start the microphone", "warn", "🎙️", 2200);
    }
  });
}

function stopVoice() {
  if (!recognition || !listening) return;
  try { recognition.stop(); } catch { /* ignore */ }
  listening = false;
  dom.micBtn.classList.remove("listening");
  dom.voiceStatus.classList.remove("on");
}

// ─────────────────────────────────────────────────────────────────────────────
//  JOYSTICK
// ─────────────────────────────────────────────────────────────────────────────
let joyPointer = null;
const joyBase = { x: 0, y: 0 };
const joyHome = { x: 90, y: 600 };
const JOY_RADIUS = 44;

function placeJoystickHome() {
  const w = window.innerWidth;
  const h = window.innerHeight;
  joyHome.x = Math.max(82, Math.min(w * 0.17, 128));
  joyHome.y = h - Math.max(112, Math.min(h * 0.15, 146));
  if (joyPointer === null) {
    dom.joystick.style.left = joyHome.x + "px";
    dom.joystick.style.top = joyHome.y + "px";
  }
}

function setKnob(dx, dy) {
  dom.stickKnob.style.transform = "translate(calc(-50% + " + dx + "px), calc(-50% + " + dy + "px))";
}

function applyJoystick(dx, dy) {
  const d = Math.hypot(dx, dy);
  if (d > JOY_RADIUS) { dx = (dx / d) * JOY_RADIUS; dy = (dy / d) * JOY_RADIUS; }
  setKnob(dx, dy);
  let nx = dx / JOY_RADIUS;
  let ny = -dy / JOY_RADIUS;
  const mag = Math.hypot(nx, ny);
  if (mag < 0.14) { nx = 0; ny = 0; }
  else {
    const k = (mag - 0.14) / (1 - 0.14);
    nx = (nx / mag) * k;
    ny = (ny / mag) * k;
  }
  input.moveX = clamp(nx, -1, 1);
  input.moveY = clamp(ny, -1, 1);
}

function resetJoystick() {
  joyPointer = null;
  input.moveX = 0;
  input.moveY = 0;
  dom.joystick.classList.remove("active");
  setKnob(0, 0);
  dom.joystick.style.transition = "left .2s ease, top .2s ease, opacity .2s, width .15s, height .15s";
  dom.joystick.style.left = joyHome.x + "px";
  dom.joystick.style.top = joyHome.y + "px";
  setTimeout(() => { if (joyPointer === null) dom.joystick.style.transition = ""; }, 240);
}

function setupJoystick() {
  dom.joystickZone.addEventListener("pointerdown", (e) => {
    if (joyPointer !== null || state.paused) return;
    e.preventDefault();
    e.stopPropagation();
    AudioFX.init();
    joyPointer = e.pointerId;
    try { dom.joystickZone.setPointerCapture(e.pointerId); } catch { /* ignore */ }
    joyBase.x = e.clientX;
    joyBase.y = e.clientY;
    dom.joystick.style.transition = "none";
    dom.joystick.style.left = e.clientX + "px";
    dom.joystick.style.top = e.clientY + "px";
    dom.joystick.classList.add("active");
    applyJoystick(0, 0);
  });
  dom.joystickZone.addEventListener("pointermove", (e) => {
    if (e.pointerId !== joyPointer) return;
    e.preventDefault();
    applyJoystick(e.clientX - joyBase.x, e.clientY - joyBase.y);
  });
  const end = (e) => {
    if (e.pointerId !== joyPointer) return;
    resetJoystick();
  };
  dom.joystickZone.addEventListener("pointerup", end);
  dom.joystickZone.addEventListener("pointercancel", end);
  dom.joystickZone.addEventListener("lostpointercapture", end);
}

// ─────────────────────────────────────────────────────────────────────────────
//  LOOK / CAMERA DRAG
// ─────────────────────────────────────────────────────────────────────────────
let lookPointer = null;
const lookLast = { x: 0, y: 0 };

function setupLook() {
  dom.lookZone.addEventListener("pointerdown", (e) => {
    if (state.paused || lookPointer !== null) return;
    if (e.pointerType === "mouse" && e.button !== 0) return;
    lookPointer = e.pointerId;
    lookLast.x = e.clientX;
    lookLast.y = e.clientY;
    try { dom.lookZone.setPointerCapture(e.pointerId); } catch { /* ignore */ }
    AudioFX.init();
  });
  dom.lookZone.addEventListener("pointermove", (e) => {
    if (e.pointerId !== lookPointer) return;
    const dx = e.clientX - lookLast.x;
    const dy = e.clientY - lookLast.y;
    lookLast.x = e.clientX;
    lookLast.y = e.clientY;
    cam.yaw -= dx * 0.0042;
    cam.pitch = clamp(cam.pitch + dy * 0.0034, -0.18, 1.18);
    cam.lastLook = state.time;
  });
  const end = (e) => { if (e.pointerId === lookPointer) lookPointer = null; };
  dom.lookZone.addEventListener("pointerup", end);
  dom.lookZone.addEventListener("pointercancel", end);
  dom.lookZone.addEventListener("lostpointercapture", end);
  dom.lookZone.addEventListener("wheel", (e) => {
    e.preventDefault();
    cam.dist = clamp(cam.dist + e.deltaY * 0.0035, 3.8, 11.5);
  }, { passive: false });
  dom.lookZone.addEventListener("contextmenu", (e) => e.preventDefault());
}

// ─────────────────────────────────────────────────────────────────────────────
//  KEYBOARD (desktop convenience)
// ─────────────────────────────────────────────────────────────────────────────
function setupKeyboard() {
  window.addEventListener("keydown", (e) => {
    if (isTyping(e.target)) {
      if (e.code === "Escape") closeAll();
      return;
    }
    AudioFX.init();
    const code = e.code;
    if (["KeyW", "KeyA", "KeyS", "KeyD", "ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", "Space"].includes(code)) {
      e.preventDefault();
    }
    if (code === "KeyW" || code === "ArrowUp") keys.w = true;
    if (code === "KeyS" || code === "ArrowDown") keys.s = true;
    if (code === "KeyA" || code === "ArrowLeft") keys.a = true;
    if (code === "KeyD" || code === "ArrowRight") keys.d = true;
    if (e.repeat) return;
    if (code === "Space") requestJump();
    else if (code === "KeyF" || code === "KeyE") useAction();
    else if (code === "KeyC") openPrompt();
    else if (code === "Escape") closeAll();
  });
  window.addEventListener("keyup", (e) => {
    const code = e.code;
    if (code === "KeyW" || code === "ArrowUp") keys.w = false;
    if (code === "KeyS" || code === "ArrowDown") keys.s = false;
    if (code === "KeyA" || code === "ArrowLeft") keys.a = false;
    if (code === "KeyD" || code === "ArrowRight") keys.d = false;
  });
  window.addEventListener("blur", () => {
    keys.w = keys.a = keys.s = keys.d = false;
    resetJoystick();
  });
}

// ─────────────────────────────────────────────────────────────────────────────
//  BUTTON / SHEET WIRING
// ─────────────────────────────────────────────────────────────────────────────
function bindPress(el, fn) {
  if (!el) return;
  el.addEventListener("pointerdown", (e) => {
    e.preventDefault();
    e.stopPropagation();
    fn();
  });
  el.addEventListener("click", (e) => {
    if (e.detail === 0) { e.preventDefault(); fn(); }
  });
}

function setupUI() {
  placeJoystickHome();
  setupJoystick();
  setupLook();
  setupKeyboard();
  setupVoice();

  dom.createBtn.addEventListener("click", (e) => { e.preventDefault(); openPrompt(); });
  dom.settingsBtn.addEventListener("click", (e) => { e.preventDefault(); openSettings(); });
  dom.closePrompt.addEventListener("click", (e) => { e.preventDefault(); closePrompt(); });
  dom.closeSettings.addEventListener("click", (e) => { e.preventDefault(); closeSettings(); });
  dom.sendBtn.addEventListener("click", (e) => { e.preventDefault(); sendPrompt(); });

  bindPress(dom.jumpBtn, requestJump);
  bindPress(dom.useBtn, useAction);

  dom.chips.addEventListener("click", (e) => {
    const chip = e.target.closest(".chip");
    if (!chip) return;
    dom.promptInput.value = chip.dataset.prompt || chip.textContent.trim();
    AudioFX.ui();
    sendPrompt();
  });

  dom.promptInput.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      sendPrompt();
    }
  });
  dom.promptInput.addEventListener("input", () => {
    dom.promptInput.style.height = "auto";
    dom.promptInput.style.height = Math.min(128, dom.promptInput.scrollHeight) + "px";
  });

  for (const overlay of [dom.promptOverlay, dom.settingsOverlay]) {
    overlay.addEventListener("click", (e) => {
      if (e.target !== overlay) return;
      if (overlay === dom.promptOverlay) closePrompt();
      else closeSettings();
    });
  }

  dom.providerSeg.addEventListener("click", (e) => {
    const btn = e.target.closest("button[data-provider]");
    if (!btn) return;
    draftProvider = btn.dataset.provider;
    [...dom.providerSeg.querySelectorAll("button")].forEach((b) => b.classList.toggle("on", b === btn));
    dom.modelInput.placeholder = defaultModel(draftProvider);
    AudioFX.ui();
  });

  dom.eyeBtn.addEventListener("click", () => {
    const show = dom.keyInput.type === "password";
    dom.keyInput.type = show ? "text" : "password";
    dom.eyeBtn.textContent = show ? "HIDE" : "SHOW";
  });

  dom.soundToggle.addEventListener("click", () => {
    settings.sound = !settings.sound;
    dom.soundToggle.classList.toggle("on", settings.sound);
    dom.soundToggle.setAttribute("aria-checked", String(settings.sound));
    AudioFX.enabled = settings.sound;
    AudioFX.init();
    if (settings.sound) AudioFX.ui();
    persistSettings();
  });

  dom.qualitySelect.addEventListener("change", () => {
    settings.quality = dom.qualitySelect.value;
    persistSettings();
    applyQuality();
    toast("Quality: " + settings.quality, "", "🎛️", 1500);
  });

  dom.saveSettings.addEventListener("click", saveSettingsFromUI);
  dom.clearWorldBtn.addEventListener("click", clearCreations);
  dom.respawnBtn.addEventListener("click", () => { closeSettings(); respawnPlayer(false); });

  document.addEventListener("gesturestart", (e) => e.preventDefault(), { passive: false });
  document.addEventListener("dblclick", (e) => e.preventDefault(), { passive: false });
  document.addEventListener("contextmenu", (e) => {
    if (e.target && e.target.tagName === "CANVAS") e.preventDefault();
  });
  window.addEventListener("pointerdown", () => AudioFX.init(), { once: true, passive: true });
  window.addEventListener("keydown", () => AudioFX.init(), { once: true });

  updateEngineNote();
  if (window.matchMedia("(hover: hover) and (pointer: fine)").matches) {
    dom.hint.innerHTML = "Tap <b>✦ Create</b> · WASD move · drag to look";
  }
  setTimeout(hideHint, 13000);
  applyQuality();
}

// ─────────────────────────────────────────────────────────────────────────────
//  HUD
// ─────────────────────────────────────────────────────────────────────────────
function updateCooldownUI() {
  const remain = Math.max(0, state.nextFire - state.time);
  const total = Math.max(0.15, state.cooldownTotal || 0.4);
  const cd = clamp(remain / total, 0, 1);
  dom.useBtn.style.setProperty("--cd", cd.toFixed(3));
  dom.useBtn.classList.toggle("ready", cd <= 0.001);
}

function updateHud() {
  updateCooldownUI();
  if (state.time - state.lastHud < 0.22) return;
  state.lastHud = state.time;
  dom.fpsCount.textContent = String(Math.round(clamp(state.fps, 1, 144)));
  updateBodyCount();

  if (state.drivingEntity) setUseLabel("EXIT");
  else if (state.nearVehicle) setUseLabel("DRIVE");
  else if (state.equipped && state.equipped.type === "weapon") setUseLabel("FIRE");
  else if (state.equipped && state.equipped.type === "physics_object") setUseLabel("DEPLOY");
  else setUseLabel("USE");
}

content.text:
Now 07-loop.js: animation loop, initGame, debug API, start.

Loop:
```js
function animate(now) {
  requestAnimationFrame(animate);
  const dt = clamp((now - lastFrame)/1000, 0.001, 0.05);
  lastFrame = now;
  if (document.hidden) return;
  state.time += dt;
  state.fps = damp(state.fps, 1/dt, 4, dt);
  updateWorldEffect(dt);
  world.step(1/60, dt, 4);
  updatePlayer(dt);
  updateEntities(dt);
  updateVehicles(dt);
  updateWeather(dt);
  updateEffects(dt);
  updateCamera(dt);
  updateSky(dt);
  updateHud();
  renderer.render(scene,camera);
}
```
Order: updateWorldEffect before physics. updateEntities after physics. updateVehicles after entities (sets velocities for next step? It sets body quaternion/velocity after step, so the visual sync for vehicle happened in updateEntities before updateVehicles; vehicle group will lag one frame. Fine, or call updateVehicles before updateEntities. But updateVehicles uses entity body position; order not critical. Better: physics step, updateVehicles (driving), updateEntities (sync). But updateEntities also handles vehicle parking. If updateVehicles sets quaternion then updateEntities syncs. Good. Change order: world.step → updatePlayer → updateVehicles → updateEntities → weather → effects → camera → sky → hud → render. But updateVehicles sets player body position while driving; updatePlayer returns early. Good.
- updateWorldEffect before step.
- updateWeather spawns entities mid-frame; fine.
- updateEffects.
- `renderer.render`.
- `state.fps` uses dt clamped 0.05, so min 20fps; okay. Use rawDt for fps? Keep.

Visibility: on `visibilitychange`, reset lastFrame. Also pause audio? skip.

Init:
```js
function initGame() {
  initEngine();
  initGeometries();
  initEffects();
  setupUI();
  // initial props? maybe none
  updateBodyCount();
  state.ready = true;
  window.__READY__ = true;
  document.body.dataset.ready='1';
  requestAnimationFrame((t)=>{ lastFrame=t; animate(t); });
  setTimeout(()=>dom.loading.classList.add('done'), 450);
  setTimeout(()=>{ if(dom.loading.parentNode) dom.loading.remove(); }, 1300);
  // welcome toast after loading
  setTimeout(()=>toast('Forge anything with ✦ Create', '', '✦', 3200), 1200);
}
```
Wait: `initEngine` calls `renderer.render` before `initGeometries`/`initEffects`, fine (no entities). But `initEffects` uses scene and glowTexture, fine.
- `setupUI` calls `applyQuality`, which sets renderer pixel ratio and size. Fine.
- `state.ready=true` before first frame; debug.
- Loading hide: after first render. We can render once in initEngine, so hide after 400ms. Use `requestAnimationFrame` to ensure.
- Start loop before hiding.
- `window.__READY__=true`.
- Set `dom.hint` visible by default.
- Maybe spawn 2 welcome crates? Let's not.

Debug API:
```js
window.__GAME__ = {
  get ready(){return state.ready;},
  state, entities, settings, input, cam, world, camera, scene, playerBody,
  createFromPrompt, localForge, applySpec, useAction, requestJump,
  openPrompt, closePrompt, openSettings, closeSettings,
  spawnLocal(q){ const s=localForge(q); applySpec(s,q); return s; },
  clearCreations, respawnPlayer,
  setMove(x,y){ input.moveX=x; input.moveY=y; },
  setLook(dx,dy){ cam.yaw -= dx; cam.pitch = clamp(cam.pitch+dy,-0.18,1.18); },
  info(){ return {entities: entities.length, equipped: state.equipped?.name||null, driving: !!state.drivingEntity, gravity: world.gravity.y, fps: state.fps, effect: state.effect?.name||null, paused: state.paused}; },
  forceSpec(spec){ const s=normalizeSpec(spec, 'debug'); applySpec(s, 'debug'); return s; }
};
```
- Expose `THREE` maybe for tests? Not needed.
- `window.__READY__ = false` at top? Set after.

Potential issue: `initEngine` references `initGeometries` and `initEffects`; I haven't added calls. I'll add in initGame before initEngine? `initEffects` needs scene; so after initEngine. But `buildPlayer` doesn't use GEO. So:
```js
initEngine();
initGeometries();
initEffects();
```
- `initEngine` renders once; no geometry needed. Fine.
- `initSky` uses glowTexture created at module top before renderer? `makeGlowTexture` uses canvas only, fine.
- `glowTexture` created before `THREE`? Wait, 03-engine.js defines `const glowTexture = makeGlowTexture();` after dynamic import (THREE available) and after `makeGlowTexture` function. Good.
- `materialCache` uses THREE? Only in visualMaterial at runtime. Fine.

- `initScenery` uses `scene.userData`, fine.
- `initGround` calls `makeGridTexture` uses renderer capabilities; renderer initialized first. Good.
- `initEngine` calls `snapCamera` which uses playerBody; initPhysics done. Good.
- `cam.target` set in initRenderer. Good.
- `renderer.render` after everything. Good.

Audio:
- `AudioFX.init` only on gesture. In createFromPrompt (called from send click) it inits. Fine.
- In initGame, no audio.

Loading hide:
```js
requestAnimationFrame((t)=>{ lastFrame=t; animate(t); });
setTimeout(()=>{ dom.loading.classList.add('done'); state.ready=true; window.__READY__=true; ... }, 350);
```
Need state.ready before tests interact. Set ready immediately after init, but hide loader after. Better:
```js
