await page.waitForTimeout(500);
const trace = await page.evaluate(async () => {
  const out = [];
  window.__GAME__.use();
  for (let i = 0; i < 10; i++) {
    await new Promise(r => setTimeout(r, 100));
    out.push({ t: i * 100, n: window.__GAME__.entities.length, info: window.__GAME__.info() });
  }
  return out;
});
console.log(JSON.stringify(trace.map(x => ({ t: x.t, n: x.n })), null, 1));
console.log('first', JSON.stringify(trace[0].info));
// fire into sky
await page.evaluate(() => { window.__GAME__.cam.pitch = -0.1; });
for (let i = 0; i < 4; i++) { await page.evaluate(() => window.__GAME__.use()); await page.waitForTimeout(350); }
await page.waitForTimeout(400);
