import { createRequire } from 'node:module';
import fs from 'node:fs';
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(fs.readFileSync(runtime + '/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + fs.readFileSync(runtime + '/display', 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: false });
const errors = [];
async function shot(name, width, height, mobile) {
  const page = await browser.newPage({ viewport: { width, height }, deviceScaleFactor: 1, hasTouch: mobile, isMobile: mobile });
  page.on('pageerror', e => errors.push(name + ' pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push(name + ' console: ' + m.text()); });
  page.on('response', r => { if (r.status() >= 400) errors.push(name + ' HTTP' + r.status() + ': ' + r.url()); });
  await page.goto('http://localhost:3000', { waitUntil: 'load', timeout: 45000 });
  await page.waitForFunction(() => window.__READY__ === true, null, { timeout: 30000 });
  await page.waitForTimeout(1600);
  await page.screenshot({ path: `/tmp/opencode/${name}.jpg`, type: 'jpeg', quality: 88 });
  console.log(name, await page.evaluate(() => window.__GAME__.info()));
  await page.close();
}
await shot('v2-mobile', 390, 844, true);
await shot('v2-small', 320, 568, true);
await shot('v2-desktop', 1280, 800, false);
console.log('errors', JSON.stringify(errors, null, 2));
await browser.close();
