import { createRequire } from 'node:module';
import fs from 'node:fs';
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(fs.readFileSync(runtime + '/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + fs.readFileSync(runtime + '/display', 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: false });
for (const [w,h,m] of [[320,568,true],[360,640,true],[390,844,true],[430,932,true],[844,390,true]]) {
  const page = await browser.newPage({ viewport:{width:w,height:h}, hasTouch:m, isMobile:m });
  await page.goto('http://localhost:3000', { waitUntil:'load' });
  await page.waitForFunction(() => window.__READY__ === true);
  await page.waitForTimeout(700);
  const res = await page.evaluate(() => {
    const ids = ['brand','createBtn','settingsBtn','stats','toasts','itemCard','actions','joystickZone','hint','useBtn','jumpBtn'];
    const boxes = {};
    for (const id of ids) {
      const el = document.getElementById(id);
      if (!el) continue;
      const r = el.getBoundingClientRect();
      if (r.width && r.height) boxes[id] = { x:+r.x.toFixed(0), y:+r.y.toFixed(0), w:+r.width.toFixed(0), h:+r.height.toFixed(0), r:+r.right.toFixed(0), b:+r.bottom.toFixed(0) };
    }
    const overlaps = [];
    const keys = Object.keys(boxes);
    for (let i=0;i<keys.length;i++) for (let j=i+1;j<keys.length;j++) {
      const a=boxes[keys[i]], b=boxes[keys[j]];
      const ox = Math.min(a.r,b.r)-Math.max(a.x,b.x);
      const oy = Math.min(a.b,b.b)-Math.max(a.y,b.y);
      if (ox>2 && oy>2) overlaps.push(`${keys[i]} x ${keys[j]} (${ox}x${oy})`);
    }
    return { boxes, overlaps, scrollW: document.documentElement.scrollWidth, innerW: innerWidth };
  });
  console.log(`\n=== ${w}x${h} ===`);
  console.log('overlaps:', res.overlaps.length ? res.overlaps : 'none');
  console.log('scroll', res.scrollW, 'inner', res.innerW);
  await page.screenshot({ path:`/tmp/opencode/layout-${w}x${h}.jpg`, type:'jpeg', quality:84 });
  await page.close();
}
await browser.close();
EOF
