import { createRequire } from 'node:module';
import fs from 'node:fs';
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(fs.readFileSync(runtime + '/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + fs.readFileSync(runtime + '/display', 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: false });
const page = await browser.newPage({ viewport:{width:390,height:844}, deviceScaleFactor:1, hasTouch:true, isMobile:true });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
page.on('response', r => { if (r.status() >= 400) errors.push('HTTP' + r.status() + ': ' + r.url()); });
await page.goto('http://localhost:3000', { waitUntil:'load', timeout:45000 });
await page.waitForFunction(() => window.__READY__ === true, null, { timeout:30000 });
await page.waitForTimeout(1400);
await page.screenshot({ path:'/tmp/opencode/final-01-start.jpg', type:'jpeg', quality:88 });

// Prompt sheet
await page.click('#createBtn');
await page.waitForTimeout(500);
await page.screenshot({ path:'/tmp/opencode/final-02-prompt.jpg', type:'jpeg', quality:88 });
await page.click('#promptClose').catch(()=>{});
await page.waitForTimeout(350);

// Settings sheet
await page.click('#settingsBtn');
await page.waitForTimeout(450);
await page.screenshot({ path:'/tmp/opencode/final-03-settings.jpg', type:'jpeg', quality:88 });
await page.click('#settingsClose').catch(()=>{});
await page.waitForTimeout(350);

// Tower + explosion gun + firing stress
await page.evaluate(() => window.__GAME__.spawnLocal('giant tower'));
await page.waitForTimeout(1200);
await page.evaluate(() => window.__GAME__.spawnLocal('rocket launcher'));
await page.waitForTimeout(700);
for (let i=0;i<8;i++) { await page.evaluate(() => window.__GAME__.use()); await page.waitForTimeout(320); }
await page.waitForTimeout(900);
console.log('after stress', await page.evaluate(() => window.__GAME__.info()));
await page.screenshot({ path:'/tmp/opencode/final-04-action.jpg', type:'jpeg', quality:88 });

// Low gravity + trampoline + rain
await page.evaluate(() => { window.__GAME__.spawnLocal('low gravity'); window.__GAME__.spawnLocal('giant trampoline'); });
await page.waitForTimeout(1000);
await page.evaluate(() => { window.__GAME__.cam.pitch = 0.42; });
await page.waitForTimeout(800);
await page.screenshot({ path:'/tmp/opencode/final-05-lowgrav.jpg', type:'jpeg', quality:88 });
await page.evaluate(() => window.__GAME__.spawnLocal('make it rain exploding watermelons'));
await page.waitForTimeout(2400);
await page.screenshot({ path:'/tmp/opencode/final-06-rain.jpg', type:'jpeg', quality:88 });

// Vehicle
await page.evaluate(() => { window.__GAME__.spawnLocal('giant car with square wheels'); });
await page.waitForTimeout(1500);
await page.evaluate(() => window.__GAME__.setMove(0, 1));
await page.waitForTimeout(1500);
console.log('drive', await page.evaluate(() => window.__GAME__.info()));
await page.screenshot({ path:'/tmp/opencode/final-07-drive.jpg', type:'jpeg', quality:88 });

// Cap
await page.evaluate(() => { for (let i=0;i<50;i++) window.__GAME__.spawnLocal('crate ' + i); });
await page.waitForTimeout(1000);
const cap = await page.evaluate(() => window.__GAME__.info());
console.log('cap', cap);
await page.screenshot({ path:'/tmp/opencode/final-08-cap.jpg', type:'jpeg', quality:88 });

// sustained fire for collision stability
await page.evaluate(() => window.__GAME__.spawnLocal('airplane gun'));
for (let i=0;i<20;i++) { await page.evaluate(() => window.__GAME__.use()); await page.waitForTimeout(200); }
await page.waitForTimeout(1200);
console.log('post-fire', await page.evaluate(() => window.__GAME__.info()));
console.log('ERRORS', JSON.stringify(errors, null, 2));
await browser.close();
EOF
